(ns rainbow.algorithms.reference.cyk
  "Executable CYK recognizer for grammars in Chomsky Normal Form, matching the
  proved rule-application decision.")

(defn rule-applies? [left-has-B? right-has-C?] (and left-has-B? right-has-C?))

(defn recognize?
  "True iff `word` (a vector of terminals) is generated by the CNF grammar with
  the given start symbol. `unit` maps terminal -> set of nonterminals (A -> a),
  `binary` is a set of [A B C] rules (A -> B C)."
  [word start unit binary]
  (let [n (count word)
        ;; table[i][len] = set of nonterminals deriving word[i..i+len]
        table (atom {})]
    (doseq [i (range n)]
      (swap! table assoc [i 1] (get unit (word i) #{})))
    (doseq [len (range 2 (inc n)), i (range (- n len -1))]
      (swap! table assoc [i len]
             (set (for [k (range 1 len)
                        [a b c] binary
                        :when (rule-applies?
                               (contains? (@table [i k]) b)
                               (contains? (@table [(+ i k) (- len k)]) c))]
                    a))))
    (contains? (@table [0 n]) start)))
